<?php
namespace App\Http\Controllers;
use App\Models\{ApplicationSetting,Product,ProductStock,TransferNote,Warehouse}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Inertia\Inertia;
class TransferNoteController { public function index(Request $r){$this->access($r);return Inertia::render('TransferNotes/Index',['notes'=>TransferNote::with(['fromWarehouse','toWarehouse','items'])->latest('issued_at')->get()]);} public function create(Request $r){$this->access($r);return Inertia::render('TransferNotes/Create',['warehouses'=>Warehouse::where('active',true)->orderBy('name')->get(),'products'=>Product::where('active',true)->orderBy('name')->get(['id','name','unit'])]);} public function store(Request $r){$this->access($r);$d=$r->validate(['from_warehouse_id'=>['required','different:to_warehouse_id','exists:warehouses,id'],'to_warehouse_id'=>['required','exists:warehouses,id'],'issued_at'=>['required','date'],'notes'=>['nullable','string'],'items'=>['required','array','min:1'],'items.*.product_id'=>['required','exists:products,id'],'items.*.quantity'=>['required','numeric','gt:0']]);DB::transaction(function()use($d,$r){$series=data_get(ApplicationSetting::value('document-series',['series'=>['transfer_note'=>'NT']]),'series.transfer_note','NT');$note=TransferNote::create(collect($d)->except('items')->all()+['number'=>$series.'-'.now()->format('Y').'-'.str_pad((string)(TransferNote::whereYear('issued_at',now()->year)->lockForUpdate()->count()+1),5,'0',STR_PAD_LEFT),'created_by'=>$r->user()->id]);foreach($d['items'] as $item){$product=Product::findOrFail($item['product_id']);$qty=(float)$item['quantity'];$source=ProductStock::where(['product_id'=>$product->id,'warehouse_id'=>$d['from_warehouse_id']])->lockForUpdate()->first();if(!$source||(float)$source->quantity<$qty)abort(422,'Stoc insuficient în gestiunea sursă pentru '.$product->name.'.');$source->decrement('quantity',$qty);ProductStock::firstOrCreate(['product_id'=>$product->id,'warehouse_id'=>$d['to_warehouse_id']],['quantity'=>0])->increment('quantity',$qty);$note->items()->create(['product_id'=>$product->id,'product_name'=>$product->name,'unit'=>$product->unit,'quantity'=>$qty]);}});return redirect()->route('transfer-notes.index')->with('success','Nota de transfer a fost salvată. Stocul total nu s-a modificat.');}private function access(Request $r):void{abort_unless($r->user()?->isAdministrator()||$r->user()?->isSalesManager(),403);} }
